<?php
namespace PharmaSure\Integrations\Adapters;
use PharmaSure\Integrations\Contracts\Adapter;
final class SignedWebhookAdapter implements Adapter{public function key():string{return 'signed_webhook';}public function type():string{return 'webhook';}public function deliver(array $config,array $payload):array{$url=esc_url_raw($config['endpoint_url']??'');$secret=(string)($config['credentials']['signing_secret']??'');if(!$url||!$secret){throw new \DomainException('Webhook endpoint and signing secret are required.');}$body=wp_json_encode($payload);$timestamp=(string)time();$signature=hash_hmac('sha256',$timestamp.'.'.$body,$secret);$response=wp_remote_post($url,array('timeout'=>15,'redirection'=>0,'headers'=>array('Content-Type'=>'application/json','X-PharmaSure-Timestamp'=>$timestamp,'X-PharmaSure-Signature'=>'sha256='.$signature),'body'=>$body));if(is_wp_error($response)){throw new \RuntimeException($response->get_error_message());}$code=wp_remote_retrieve_response_code($response);return array('success'=>$code>=200&&$code<300,'code'=>$code,'body'=>substr(wp_remote_retrieve_body($response),0,1000));}}
